-- =============================================================================
-- Bloom core schema (V1)
-- Conventions:
--   * UUID primary keys, generated by the application.
--   * All timestamps are TIMESTAMPTZ stored in UTC; calendar dates are DATE and are
--     interpreted in the workspace timezone (workspace.timezone).
--   * Money is NUMERIC(14,2) + ISO-4217 currency VARCHAR(3).
--   * Enumerations are VARCHAR + CHECK constraints (portable, easy to extend).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Workspace (local/demo context — Bloom app authentication is deferred)
-- -----------------------------------------------------------------------------
CREATE TABLE workspace (
    id               UUID PRIMARY KEY,
    name             VARCHAR(120) NOT NULL,
    timezone         VARCHAR(64)  NOT NULL DEFAULT 'UTC',
    default_currency VARCHAR(3)      NOT NULL DEFAULT 'USD',
    is_demo          BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- -----------------------------------------------------------------------------
-- Social: providers, connected accounts, credentials, OAuth sessions, sync jobs
-- -----------------------------------------------------------------------------
CREATE TABLE social_provider (
    code         VARCHAR(32) PRIMARY KEY,
    display_name VARCHAR(64) NOT NULL,
    api_family   VARCHAR(128) NOT NULL,
    docs_url     VARCHAR(512) NOT NULL
);

INSERT INTO social_provider (code, display_name, api_family, docs_url) VALUES
    ('INSTAGRAM', 'Instagram', 'Instagram API with Instagram Login', 'https://developers.facebook.com/docs/instagram-platform/instagram-api-with-instagram-login'),
    ('YOUTUBE',   'YouTube',   'YouTube Data API v3 + YouTube Analytics API', 'https://developers.google.com/youtube/v3'),
    ('TIKTOK',    'TikTok',    'TikTok Login Kit + Display API', 'https://developers.tiktok.com/doc/display-api-overview');

CREATE TABLE connected_social_account (
    id                       UUID PRIMARY KEY,
    workspace_id             UUID         NOT NULL REFERENCES workspace (id) ON DELETE CASCADE,
    provider                 VARCHAR(32)  NOT NULL REFERENCES social_provider (code),
    provider_account_id      VARCHAR(128) NOT NULL,
    handle                   VARCHAR(128),
    display_name             VARCHAR(256),
    avatar_url               VARCHAR(1024),
    account_type             VARCHAR(64),
    data_mode                VARCHAR(16)  NOT NULL CHECK (data_mode IN ('LIVE', 'DEMO')),
    connection_status        VARCHAR(32)  NOT NULL CHECK (connection_status IN
                                 ('ACTIVE', 'EXPIRED', 'PERMISSION_DENIED', 'REVOKED', 'DISCONNECTED', 'ERROR')),
    granted_scopes           TEXT[]       NOT NULL DEFAULT '{}',
    capabilities             TEXT[]       NOT NULL DEFAULT '{}',
    last_sync_at             TIMESTAMPTZ,
    last_successful_sync_at  TIMESTAMPTZ,
    last_sync_error          VARCHAR(512),
    connected_at             TIMESTAMPTZ  NOT NULL DEFAULT now(),
    disconnected_at          TIMESTAMPTZ,
    created_at               TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at               TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_account_provider_identity UNIQUE (provider, provider_account_id)
);
CREATE INDEX ix_account_workspace_status ON connected_social_account (workspace_id, connection_status);

CREATE TABLE provider_token_credential (
    id                       UUID PRIMARY KEY,
    account_id               UUID        NOT NULL UNIQUE REFERENCES connected_social_account (id) ON DELETE CASCADE,
    access_token_ciphertext  TEXT        NOT NULL,
    refresh_token_ciphertext TEXT,
    key_version              INTEGER     NOT NULL,
    token_type               VARCHAR(32),
    scopes                   TEXT[]      NOT NULL DEFAULT '{}',
    access_expires_at        TIMESTAMPTZ,
    refresh_expires_at       TIMESTAMPTZ,
    created_at               TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at               TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE oauth_connect_session (
    id                     UUID PRIMARY KEY,
    workspace_id           UUID         NOT NULL REFERENCES workspace (id) ON DELETE CASCADE,
    provider               VARCHAR(32)  NOT NULL REFERENCES social_provider (code),
    state_hash             VARCHAR(64)     NOT NULL UNIQUE,
    code_verifier_ciphertext TEXT,
    redirect_uri           VARCHAR(1024) NOT NULL,
    status                 VARCHAR(32)  NOT NULL CHECK (status IN
                               ('PENDING', 'AWAITING_SELECTION', 'COMPLETED', 'FAILED', 'EXPIRED', 'CANCELLED')),
    token_set_ciphertext   TEXT,
    candidates             JSONB        NOT NULL DEFAULT '[]',
    connected_account_ids  UUID[]       NOT NULL DEFAULT '{}',
    error_code             VARCHAR(64),
    error_message          VARCHAR(512),
    expires_at             TIMESTAMPTZ  NOT NULL,
    created_at             TIMESTAMPTZ  NOT NULL DEFAULT now(),
    completed_at           TIMESTAMPTZ
);
CREATE INDEX ix_connect_session_workspace ON oauth_connect_session (workspace_id, created_at DESC);

CREATE TABLE sync_job (
    id             UUID PRIMARY KEY,
    account_id     UUID        NOT NULL REFERENCES connected_social_account (id) ON DELETE CASCADE,
    trigger_type   VARCHAR(16) NOT NULL CHECK (trigger_type IN ('MANUAL', 'SCHEDULED', 'CONNECT')),
    status         VARCHAR(16) NOT NULL CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'PARTIAL', 'FAILED')),
    attempt        INTEGER     NOT NULL DEFAULT 0,
    items_fetched  INTEGER     NOT NULL DEFAULT 0,
    cursor_state   JSONB       NOT NULL DEFAULT '{}',
    error_code     VARCHAR(64),
    error_message  VARCHAR(512),
    next_retry_at  TIMESTAMPTZ,
    started_at     TIMESTAMPTZ,
    finished_at    TIMESTAMPTZ,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ix_sync_job_account_created ON sync_job (account_id, created_at DESC);
CREATE INDEX ix_sync_job_status ON sync_job (status, next_retry_at);

-- -----------------------------------------------------------------------------
-- Analytics: metric catalogue, account-level snapshots (incl. audience dimensions),
-- posts and post-level snapshots. NULL value + availability != AVAILABLE means
-- "not available" — never zero.
-- -----------------------------------------------------------------------------
CREATE TABLE metric_definition (
    metric_key      VARCHAR(96) PRIMARY KEY,
    provider        VARCHAR(32) NOT NULL REFERENCES social_provider (code),
    source_metric   VARCHAR(96) NOT NULL,
    canonical_key   VARCHAR(48) NOT NULL,
    scope           VARCHAR(16) NOT NULL CHECK (scope IN ('ACCOUNT', 'POST', 'AUDIENCE')),
    label           VARCHAR(96) NOT NULL,
    description     VARCHAR(512) NOT NULL,
    unit            VARCHAR(16) NOT NULL CHECK (unit IN ('COUNT', 'MINUTES', 'SECONDS', 'PERCENT')),
    measure_type    VARCHAR(16) NOT NULL CHECK (measure_type IN ('STOCK', 'FLOW')),
    api_source      VARCHAR(128) NOT NULL
);

CREATE TABLE analytics_snapshot (
    id              UUID PRIMARY KEY,
    account_id      UUID         NOT NULL REFERENCES connected_social_account (id) ON DELETE CASCADE,
    metric_key      VARCHAR(96)  NOT NULL REFERENCES metric_definition (metric_key),
    snapshot_date   DATE         NOT NULL,
    time_window     VARCHAR(16)  NOT NULL CHECK (time_window IN ('DAY', 'LIFETIME', 'PERIOD_28D')),
    dimension_key   VARCHAR(160) NOT NULL DEFAULT '',
    dimensions      JSONB        NOT NULL DEFAULT '{}',
    value           NUMERIC(20, 4),
    availability    VARCHAR(24)  NOT NULL CHECK (availability IN
                        ('AVAILABLE', 'NOT_SUPPORTED', 'PERMISSION_MISSING', 'NOT_ENOUGH_DATA', 'DELAYED')),
    source_endpoint VARCHAR(256) NOT NULL,
    api_version     VARCHAR(32),
    is_demo         BOOLEAN      NOT NULL DEFAULT FALSE,
    fetched_at      TIMESTAMPTZ  NOT NULL,
    CONSTRAINT uq_snapshot UNIQUE (account_id, metric_key, snapshot_date, time_window, dimension_key)
);
CREATE INDEX ix_snapshot_account_date ON analytics_snapshot (account_id, snapshot_date);
CREATE INDEX ix_snapshot_metric_date ON analytics_snapshot (metric_key, snapshot_date);

CREATE TABLE social_post (
    id                   UUID PRIMARY KEY,
    account_id           UUID         NOT NULL REFERENCES connected_social_account (id) ON DELETE CASCADE,
    provider             VARCHAR(32)  NOT NULL REFERENCES social_provider (code),
    provider_content_id  VARCHAR(128) NOT NULL,
    content_type         VARCHAR(32)  NOT NULL,
    title                VARCHAR(512),
    permalink            VARCHAR(1024),
    thumbnail_url        VARCHAR(1024),
    published_at         TIMESTAMPTZ  NOT NULL,
    duration_seconds     INTEGER,
    is_demo              BOOLEAN      NOT NULL DEFAULT FALSE,
    fetched_at           TIMESTAMPTZ  NOT NULL,
    created_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_post_provider_identity UNIQUE (provider, account_id, provider_content_id)
);
CREATE INDEX ix_post_account_published ON social_post (account_id, published_at DESC);

CREATE TABLE post_metric_snapshot (
    id              UUID PRIMARY KEY,
    post_id         UUID         NOT NULL REFERENCES social_post (id) ON DELETE CASCADE,
    metric_key      VARCHAR(96)  NOT NULL REFERENCES metric_definition (metric_key),
    snapshot_date   DATE         NOT NULL,
    value           NUMERIC(20, 4),
    availability    VARCHAR(24)  NOT NULL CHECK (availability IN
                        ('AVAILABLE', 'NOT_SUPPORTED', 'PERMISSION_MISSING', 'NOT_ENOUGH_DATA', 'DELAYED')),
    source_endpoint VARCHAR(256) NOT NULL,
    api_version     VARCHAR(32),
    fetched_at      TIMESTAMPTZ  NOT NULL,
    CONSTRAINT uq_post_snapshot UNIQUE (post_id, metric_key, snapshot_date)
);
CREATE INDEX ix_post_snapshot_post ON post_metric_snapshot (post_id, snapshot_date DESC);

-- -----------------------------------------------------------------------------
-- Goals
-- -----------------------------------------------------------------------------
CREATE TABLE goal (
    id                 UUID PRIMARY KEY,
    workspace_id       UUID          NOT NULL REFERENCES workspace (id) ON DELETE CASCADE,
    title              VARCHAR(200)  NOT NULL,
    category           VARCHAR(32)   NOT NULL CHECK (category IN
                           ('AUDIENCE', 'CONTENT', 'REVENUE', 'ENGAGEMENT', 'SKILL', 'PERSONAL')),
    description        TEXT,
    unit               VARCHAR(48)   NOT NULL,
    start_value        NUMERIC(20, 4) NOT NULL DEFAULT 0,
    target_value       NUMERIC(20, 4) NOT NULL,
    current_value      NUMERIC(20, 4) NOT NULL DEFAULT 0,
    start_date         DATE          NOT NULL,
    deadline           DATE,
    progress_source    VARCHAR(16)   NOT NULL CHECK (progress_source IN ('MANUAL', 'ANALYTICS')),
    linked_account_id  UUID REFERENCES connected_social_account (id) ON DELETE SET NULL,
    linked_metric_key  VARCHAR(96) REFERENCES metric_definition (metric_key),
    status             VARCHAR(16)   NOT NULL CHECK (status IN ('ACTIVE', 'COMPLETED', 'ARCHIVED')),
    completed_at       TIMESTAMPTZ,
    created_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT ck_goal_analytics_link CHECK (
        progress_source = 'MANUAL' OR (linked_account_id IS NOT NULL AND linked_metric_key IS NOT NULL))
);
CREATE INDEX ix_goal_workspace_status ON goal (workspace_id, status, deadline);

CREATE TABLE goal_milestone (
    id            UUID PRIMARY KEY,
    goal_id       UUID           NOT NULL REFERENCES goal (id) ON DELETE CASCADE,
    title         VARCHAR(200)   NOT NULL,
    target_value  NUMERIC(20, 4),
    due_date      DATE,
    achieved_at   TIMESTAMPTZ,
    position      INTEGER        NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ    NOT NULL DEFAULT now()
);
CREATE INDEX ix_milestone_goal ON goal_milestone (goal_id, position);

CREATE TABLE goal_progress_entry (
    id           UUID PRIMARY KEY,
    goal_id      UUID           NOT NULL REFERENCES goal (id) ON DELETE CASCADE,
    value        NUMERIC(20, 4) NOT NULL,
    source       VARCHAR(16)    NOT NULL CHECK (source IN ('MANUAL', 'ANALYTICS')),
    note         VARCHAR(500),
    recorded_at  TIMESTAMPTZ    NOT NULL
);
CREATE INDEX ix_progress_goal_recorded ON goal_progress_entry (goal_id, recorded_at DESC);

-- -----------------------------------------------------------------------------
-- Brand & Earnings (manual tracking only)
-- -----------------------------------------------------------------------------
CREATE TABLE brand_contact (
    id            UUID PRIMARY KEY,
    workspace_id  UUID         NOT NULL REFERENCES workspace (id) ON DELETE CASCADE,
    brand_name    VARCHAR(160) NOT NULL,
    contact_name  VARCHAR(160),
    email         VARCHAR(254),
    phone         VARCHAR(48),
    website       VARCHAR(512),
    notes         TEXT,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE INDEX ix_brand_workspace_name ON brand_contact (workspace_id, brand_name);

CREATE TABLE campaign (
    id                 UUID PRIMARY KEY,
    workspace_id       UUID          NOT NULL REFERENCES workspace (id) ON DELETE CASCADE,
    brand_contact_id   UUID          NOT NULL REFERENCES brand_contact (id) ON DELETE RESTRICT,
    name               VARCHAR(200)  NOT NULL,
    stage              VARCHAR(16)   NOT NULL CHECK (stage IN
                           ('LEAD', 'CONTACTED', 'NEGOTIATING', 'CONFIRMED', 'IN_PROGRESS', 'DELIVERED', 'PAID', 'ARCHIVED')),
    agreed_amount      NUMERIC(14, 2),
    currency           VARCHAR(3)       NOT NULL,
    start_date         DATE,
    end_date           DATE,
    notes              TEXT,
    created_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT ck_campaign_amount CHECK (agreed_amount IS NULL OR agreed_amount >= 0)
);
CREATE INDEX ix_campaign_workspace_stage ON campaign (workspace_id, stage);
CREATE INDEX ix_campaign_brand ON campaign (brand_contact_id);

CREATE TABLE payment_record (
    id                 UUID PRIMARY KEY,
    campaign_id        UUID          NOT NULL REFERENCES campaign (id) ON DELETE CASCADE,
    amount             NUMERIC(14, 2) NOT NULL CHECK (amount >= 0),
    currency           VARCHAR(3)       NOT NULL,
    invoice_reference  VARCHAR(96),
    invoiced_date      DATE,
    due_date           DATE,
    paid_date          DATE,
    note               VARCHAR(500),
    created_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ   NOT NULL DEFAULT now()
);
CREATE INDEX ix_payment_campaign ON payment_record (campaign_id);
CREATE INDEX ix_payment_due ON payment_record (due_date) WHERE paid_date IS NULL;

-- -----------------------------------------------------------------------------
-- Content Studio
-- -----------------------------------------------------------------------------
CREATE TABLE content_idea (
    id            UUID PRIMARY KEY,
    workspace_id  UUID         NOT NULL REFERENCES workspace (id) ON DELETE CASCADE,
    title         VARCHAR(200) NOT NULL,
    notes         TEXT,
    platform      VARCHAR(32) REFERENCES social_provider (code),
    tags          TEXT[]       NOT NULL DEFAULT '{}',
    status        VARCHAR(16)  NOT NULL CHECK (status IN ('OPEN', 'PROMOTED', 'ARCHIVED')),
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE INDEX ix_idea_workspace_status ON content_idea (workspace_id, status);

CREATE TABLE content_draft (
    id                  UUID PRIMARY KEY,
    workspace_id        UUID          NOT NULL REFERENCES workspace (id) ON DELETE CASCADE,
    idea_id             UUID REFERENCES content_idea (id) ON DELETE SET NULL,
    parent_draft_id     UUID REFERENCES content_draft (id) ON DELETE SET NULL,
    title               VARCHAR(200)  NOT NULL,
    platform            VARCHAR(32)   NOT NULL REFERENCES social_provider (code),
    content_type        VARCHAR(16)   NOT NULL CHECK (content_type IN
                            ('POST', 'CAROUSEL', 'REEL', 'STORY', 'SHORT', 'VIDEO', 'LIVE')),
    caption             TEXT,
    script              TEXT,
    hashtags            TEXT[]        NOT NULL DEFAULT '{}',
    notes               TEXT,
    planned_date        DATE,
    stage               VARCHAR(16)   NOT NULL CHECK (stage IN ('SCRIPT', 'IN_PRODUCTION', 'READY', 'PUBLISHED')),
    goal_id             UUID REFERENCES goal (id) ON DELETE SET NULL,
    campaign_id         UUID REFERENCES campaign (id) ON DELETE SET NULL,
    published_at        TIMESTAMPTZ,
    published_url       VARCHAR(1024),
    publication_source  VARCHAR(16) CHECK (publication_source IN ('MANUAL', 'VERIFIED_API')),
    social_post_id      UUID REFERENCES social_post (id) ON DELETE SET NULL,
    current_version     INTEGER       NOT NULL DEFAULT 1,
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT ck_draft_published CHECK (
        stage <> 'PUBLISHED' OR (published_at IS NOT NULL AND publication_source IS NOT NULL))
);
CREATE INDEX ix_draft_workspace_stage ON content_draft (workspace_id, stage);
CREATE INDEX ix_draft_planned ON content_draft (workspace_id, planned_date);

CREATE TABLE content_version (
    id              UUID PRIMARY KEY,
    draft_id        UUID         NOT NULL REFERENCES content_draft (id) ON DELETE CASCADE,
    version_number  INTEGER      NOT NULL,
    snapshot        JSONB        NOT NULL,
    change_summary  VARCHAR(300),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_content_version UNIQUE (draft_id, version_number)
);

CREATE TABLE deliverable (
    id                UUID PRIMARY KEY,
    campaign_id       UUID         NOT NULL REFERENCES campaign (id) ON DELETE CASCADE,
    title             VARCHAR(200) NOT NULL,
    platform          VARCHAR(32) REFERENCES social_provider (code),
    due_date          DATE,
    status            VARCHAR(16)  NOT NULL CHECK (status IN
                          ('PLANNED', 'IN_PROGRESS', 'SUBMITTED', 'APPROVED', 'PUBLISHED')),
    content_draft_id  UUID REFERENCES content_draft (id) ON DELETE SET NULL,
    notes             TEXT,
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE INDEX ix_deliverable_campaign ON deliverable (campaign_id);
CREATE INDEX ix_deliverable_due ON deliverable (due_date);

-- -----------------------------------------------------------------------------
-- Planly: daily plans, tasks, subtasks, daily notes
-- -----------------------------------------------------------------------------
CREATE TABLE daily_plan (
    id            UUID PRIMARY KEY,
    workspace_id  UUID         NOT NULL REFERENCES workspace (id) ON DELETE CASCADE,
    plan_date     DATE         NOT NULL,
    focus         VARCHAR(300),
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_daily_plan UNIQUE (workspace_id, plan_date)
);

CREATE TABLE task (
    id                    UUID PRIMARY KEY,
    workspace_id          UUID         NOT NULL REFERENCES workspace (id) ON DELETE CASCADE,
    title                 VARCHAR(200) NOT NULL,
    description           TEXT,
    due_date              DATE,
    due_time              TIME,
    priority              VARCHAR(8)   NOT NULL CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH', 'URGENT')),
    status                VARCHAR(16)  NOT NULL CHECK (status IN ('TODO', 'IN_PROGRESS', 'DONE', 'CANCELLED')),
    recurrence            VARCHAR(16)  NOT NULL DEFAULT 'NONE' CHECK (recurrence IN ('NONE', 'DAILY', 'WEEKLY', 'MONTHLY')),
    recurrence_until      DATE,
    recurrence_source_id  UUID REFERENCES task (id) ON DELETE SET NULL,
    goal_id               UUID REFERENCES goal (id) ON DELETE SET NULL,
    content_draft_id      UUID REFERENCES content_draft (id) ON DELETE SET NULL,
    completed_at          TIMESTAMPTZ,
    created_at            TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT ck_task_recurrence_needs_date CHECK (recurrence = 'NONE' OR due_date IS NOT NULL)
);
CREATE INDEX ix_task_workspace_due ON task (workspace_id, due_date);
CREATE INDEX ix_task_workspace_status ON task (workspace_id, status);
CREATE INDEX ix_task_goal ON task (goal_id);

CREATE TABLE subtask (
    id          UUID PRIMARY KEY,
    task_id     UUID         NOT NULL REFERENCES task (id) ON DELETE CASCADE,
    title       VARCHAR(200) NOT NULL,
    done        BOOLEAN      NOT NULL DEFAULT FALSE,
    position    INTEGER      NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE INDEX ix_subtask_task ON subtask (task_id, position);

CREATE TABLE daily_note (
    id            UUID PRIMARY KEY,
    workspace_id  UUID         NOT NULL REFERENCES workspace (id) ON DELETE CASCADE,
    note_date     DATE         NOT NULL,
    body          TEXT         NOT NULL DEFAULT '',
    version       INTEGER      NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_daily_note UNIQUE (workspace_id, note_date)
);
